/**
 * Why a call into the direct-transfer rules failed. Every variant carries a
 * stable `code`; none carries a URL.
 */
sealed class DirectTransferException: kotlin.Exception() {
    
    /**
     * A storage link was refused: `malformed`, `not_https`, `userinfo`,
     * `ip_literal`, `loopback`, `bad_host`, `port`, `host_not_listed`,
     * `bucket_not_listed`, `bad_path`.
     */
    class LinkRefused(
        
        val `code`: kotlin.String
        ) : DirectTransferException() {
        override val message
            get() = "code=${ `code` }"
    }
    
    /**
     * The discovery body could not be decoded: `discovery_too_large`,
     * `discovery_malformed`.
     */
    class Discovery(
        
        val `code`: kotlin.String
        ) : DirectTransferException() {
        override val message
            get() = "code=${ `code` }"
    }
    
    /**
     * A call that does not fit the caller-driven state (a bug in the caller): the planner's
     * `not_in_flight`, `not_fetched`, `out_of_order`, `api_route_failure`; or `finished`, which
     * means the storage body handle was used after `finish` (the count was already consumed).
     */
    class Plan(
        
        val `code`: kotlin.String
        ) : DirectTransferException() {
        override val message
            get() = "code=${ `code` }"
    }
    
    /**
     * `call` was none of `discovery`, `download_grant`, `pinned_chunk`.
     */
    class UnknownCall(
        ) : DirectTransferException() {
        override val message
            get() = ""
    }
    
    /**
     * A storage body operation failed: `failed` (the head was not a `200` of the grant's length,
     * or a push would have passed the grant). The kind is core's `StorageGet::kind`; `status` is
     * the status the head (or the refused push) answered, so the caller never re-derives it.
     * Appended last so every earlier variant keeps its wire index.
     */
    class StorageBody(
        
        val `code`: kotlin.String, 
        
        val `status`: kotlin.UShort
        ) : DirectTransferException() {
        override val message
            get() = "code=${ `code` }, status=${ `status` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DirectTransferException> {
        override fun lift(error_buf: RustBuffer.ByValue): DirectTransferException = FfiConverterTypeDirectTransferError.lift(error_buf)
    }

    
}

