sealed class ServiceException: kotlin.Exception() {
    
    class InvalidInput(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class SessionRequired(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class Authentication(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class Network(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class Storage(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class Crypto(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class ManagedByService(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    /**
     * Core's Backups rule refused the change. `detail` is core's words, to
     * be shown as they are (backup spec Amendments 6 to 8). Never `message`:
     * a UniFFI error field of that name collides with Kotlin's
     * `Exception.message` (tests/error_fields.rs).
     */
    class Protected(
        
        val `detail`: kotlin.String
        ) : ServiceException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Quota(
        
        val `limitBytes`: kotlin.ULong?, 
        
        val `usedBytes`: kotlin.ULong?
        ) : ServiceException() {
        override val message
            get() = "limitBytes=${ `limitBytes` }, usedBytes=${ `usedBytes` }"
    }
    
    class SessionExpired(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class RetryAfter(
        
        val `seconds`: kotlin.ULong
        ) : ServiceException() {
        override val message
            get() = "seconds=${ `seconds` }"
    }
    
    class AnchorExpired(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class AnotherAccountOnDevice(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    class Unavailable(
        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    /**
     * The backup is off and could not finish its stop when the backup
     * service was made, so none was made. `reason` is the stop's core wire
     * string: show `backup_stop_words` for it as for a stopped batch, then
     * make the service again later.
     */
    class BackupStopUnfinished(
        
        val `reason`: kotlin.String
        ) : ServiceException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ServiceException> {
        override fun lift(error_buf: RustBuffer.ByValue): ServiceException = FfiConverterTypeServiceError.lift(error_buf)
    }

    
}

